def by_project(db: Session, scope: Scope) -> Dict:
    """Entries / exits / distinct visitors per project over the period (bar chart)."""
    of = _projects_of_visitors(db)
    rows = (
        _logs(
            db.query(
                models.VisitorLog.visitor_dbid, _ACTION, func.count(models.VisitorLog.id)
            ).filter(_ACTION.in_(("entry", "exit"))),
            scope,
            scope.start_dt,
            scope.end_dt,
        )
        .group_by(models.VisitorLog.visitor_dbid, _ACTION)
        .all()
    )
    acc: Dict[str, dict] = {}
    for dbid, action, n in rows:
        p = of.get(dbid)
        if p is None:  # the visitor was deleted
            continue
        d = acc.setdefault(p, {"entry": 0, "exit": 0, "people": set()})
        d[action] += n
        if action == "entry":
            d["people"].add(dbid)
    names = sorted(acc, key=lambda p: (p == NO_PROJECT, p))
    return {
        "labels": names,
        "entries": [acc[p]["entry"] for p in names],
        "exits": [acc[p]["exit"] for p in names],
        "unique": [len(acc[p]["people"]) for p in names],
    }


def expiry_status(db: Session, scope: Scope, today: Optional[date] = None) -> Dict:
    """How many visitors (of the project) have an expired / expiring / valid / no readable expiry."""
    today = today or date.today()
    c = {"expired": 0, "expiring": 0, "ok": 0, "none": 0}
    for dbid, props in db.query(models.Visitor.dbid, models.Visitor.properties).all():
        if scope.ids is not None and dbid not in scope.ids:
            continue
        info = expiry_info(props or {}, today)
        c[info["status"] if info else "none"] += 1
    labels = ["פג תוקף", "עומד לפוג", "בתוקף", "ללא תוקף"]
    return {"labels": labels, "counts": [c["expired"], c["expiring"], c["ok"], c["none"]]}


